import assert from 'node:assert/strict';
import fs from 'node:fs';
import {spawnSync} from 'node:child_process';
import path from 'node:path';
import {buildStatement} from '../g4-release-integration-20261021/tree/windows/node/release-channel.mjs';
const dir=fs.mkdtempSync(path.resolve('work/root-release-assembly-20261022/test-'));
const paths=['zip','setup','manifest'].map((name,i)=>{const p=path.join(dir,name);fs.writeFileSync(p,Buffer.alloc(1024*(i+1),i+65));return p;});
const at='2026-10-22T04:00:00.000Z';
const verifier=path.resolve('work/g4-release-integration-20261021/tree/windows/node/release-channel.mjs');
const script=path.resolve('work/root-release-assembly-20261022/statement-stream.mjs');
const output=path.join(dir,'statement.json');
const args=[script,verifier,'stable','2026.10.22.1',...paths,output,at];
const r=spawnSync(process.execPath,args,{encoding:'utf8',timeout:15000});assert.equal(r.status,0,r.stderr);
assert.deepEqual(JSON.parse(fs.readFileSync(output,'utf8')),buildStatement({channel:'stable',version:'2026.10.22.1',zip:paths[0],setup:paths[1],manifest:paths[2],issuedAt:at}));
assert.notEqual(spawnSync(process.execPath,args,{encoding:'utf8',timeout:15000}).status,0,'must not overwrite existing statement');
fs.writeFileSync(paths[0],'');
args[7]=path.join(dir,'invalid.json');
assert.notEqual(spawnSync(process.execPath,args,{encoding:'utf8',timeout:15000}).status,0,'empty artifacts must be refused');
assert.equal(fs.existsSync(args[7]),false);
console.log('PASS: exact statement equality with pinned buildStatement, existing-file refusal, empty-artifact refusal');
fs.rmSync(dir,{recursive:true});
